/// Generates the Zsh completion script for [executableName].
///
/// The script can be sourced (`source <(exe completion zsh)`) or saved as
/// `_exe` in a directory on `$fpath` for autoloading.
String zshCompletionScript(final String executableName) {
  return _template.replaceAll('__EXE__', executableName);
}

const _template = r'''
#compdef __EXE__
compdef ___EXE__ __EXE__

# zsh completion for __EXE__                                -*- shell-script -*-
#
# Generated by `__EXE__ completion zsh`. Install once, for example by adding
#   source <(__EXE__ completion zsh)
# to ~/.zshrc after compinit, or by saving it as `___EXE__` in a directory
# on $fpath.
#
# The script contains no commands or options. It asks the executable for the
# completion alternatives (`__EXE__ __complete ...`), so it keeps working when
# the executable is updated.

___EXE__()
{
    local directiveError=1 directiveNoSpace=2 directiveNoFiles=4
    local directiveFileExt=8 directiveDirs=16 directiveKeepOrder=32

    local cur=${words[CURRENT]} cmd out lastLine directive=0 line comp
    local -a completions compaddOpts describeOpts

    # The cursor may have been moved back: complete up to the cursor word.
    words=("${(@)words[1,CURRENT]}")

    # When completing `--option=value`, the response holds the bare values
    # which are inserted after the option prefix.
    if [[ $cur == -*=* ]]; then
        compaddOpts+=(-P "${cur%%=*}=")
    fi

    cmd=${(Q)words[1]}
    [[ $cmd == '~'* ]] && cmd=${HOME}${cmd#'~'}

    # The completion request: the words before the cursor word, then the
    # (possibly empty) cursor word.
    out=$("$cmd" __complete "${(@Q)words[2,-1]}" 2>/dev/null)

    # The last line of the response is the directive, e.g. ':4'.
    lastLine=${out##*$'\n'}
    if [[ $lastLine == :* ]]; then
        directive=${lastLine#:}
        if [[ $out == "$lastLine" ]]; then
            out=''
        else
            out=${out%$'\n'*}
        fi
    fi
    [[ $directive == <-> ]] || directive=0

    (( directive & directiveError )) && return 1
    (( directive & directiveNoSpace )) && compaddOpts+=(-S '')
    (( directive & directiveKeepOrder )) && describeOpts+=(-V)

    for line in ${(f)out}; do
        [[ -z $line ]] && continue
        # value<TAB>description becomes value:description for _describe,
        # with ':' in the value escaped.
        comp=${line%%$'\t'*}
        comp=${comp//:/\\:}
        if [[ $line == *$'\t'* ]]; then
            comp="$comp:${line#*$'\t'}"
        fi
        completions+=("$comp")
    done

    if (( directive & directiveFileExt )); then
        # The completions are the file extensions: one glob matching any.
        _files -g "*.(${(j:|:)completions})" "${compaddOpts[@]}"
    elif (( directive & directiveDirs )); then
        _files -/ "${compaddOpts[@]}"
    else
        if (( ${#completions} )) &&
            _describe "${describeOpts[@]}" -t values 'values' completions \
                "${compaddOpts[@]}"; then
            return 0
        fi
        # Nothing matched: file completion unless disabled. Returning 1 lets
        # zsh try other matchers, such as matching in the middle of words.
        (( directive & directiveNoFiles )) && return 1
        _files "${compaddOpts[@]}"
    fi
}

# Run the completion when autoloaded from $fpath by compinit (the file body
# is then the function body), but not when sourced or eval-ed.
if [[ $funcstack[1] == ___EXE__ && ${zsh_eval_context[-1]} == loadautofunc ]]
then
    ___EXE__
fi
''';
